-- The two checklists published on 2026-10-22: Getting Back Into Dating
-- (Dating) and The Week You Pack Up a Home (Moving).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-22`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-back-into-dating', 'Getting Back Into Dating', 'For getting back out there after a long gap or a bad stretch. It helps you decide what you are looking for, keep the apps to a set time, move to a short meeting early, and read a run of dead ends as the process rather than a verdict.', 'Dating', '["Decide what you are actually looking for — company this month and a partner for life need different choices.", "Put one honest photo of your face up — a flattering old one only delays the meeting.", "Write a profile line you would say out loud — nothing in it should need a translator.", "Give yourself a cap on the apps — twenty minutes a day keeps it a hobby, not a second job.", "Move to a short meeting early — a coffee tells you more than three weeks of texting.", "Tell a friend where you are going — a text before and after is ordinary, not dramatic.", "Expect most of them to go nowhere — that is the process working, not you failing.", "Take a week off when it goes flat — the tiredness is real and it passes with a pause.", "Keep one thing in the week that is not dating — a full life is what you are bringing to this."]'::jsonb, 'as needed', array['Self-Esteem', 'Relationships']::text[], 1, '2026-10-22T16:00:00+00:00'::timestamptz),
  ('the-week-you-pack-up-a-home', 'The Week You Pack Up a Home', 'For the week before a move, when the whole house has to go in boxes. It starts in the room you use least, puts the documents and the first-night things where you can find them, and leaves a chair out until the end.', 'Moving', '["Start with the room you use least — momentum has to come from somewhere easy.", "Pack one box of first-night things — kettle, sheets, chargers, toilet paper, a mug.", "Label by room and by urgency — “kitchen, open first” saves a whole evening later.", "Decide the keep-or-go rule once — if it has not been used in a year, it travels at a cost.", "Photograph anything you take apart — the reassembly is next week''s problem already.", "Put the documents in a bag you carry — passports and leases do not ride in the truck.", "Keep one chair and one lamp out till last — a house with nowhere to sit speeds nothing up.", "Book help for the heavy hour — the stairs are where moves go wrong.", "Say goodbye to the place on purpose — one walk through the empty rooms is worth taking."]'::jsonb, 'as needed', array['Life Transitions', 'Stress']::text[], 1, '2026-10-22T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
